package com.drogaria.backend.service;
import com.drogaria.backend.dto.*; import com.drogaria.backend.entity.*; import com.drogaria.backend.exception.ApiException; import com.drogaria.backend.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.util.List;
@Service public class EstoqueService { private final EstoqueRepository r; private final ProdutoRepository produtos; private final LojaRepository lojas; public EstoqueService(EstoqueRepository r,ProdutoRepository p,LojaRepository l){this.r=r;produtos=p;lojas=l;} public List<EstoqueResponse> listar(){return r.findAll().stream().map(EstoqueResponse::new).toList();} public EstoqueResponse buscar(Integer id){return new EstoqueResponse(r.findById(id).orElseThrow(()->new ApiException("Estoque nao encontrado",HttpStatus.NOT_FOUND)));} public EstoqueResponse salvar(EstoqueRequest x){Estoque e=r.findByProdutoIdProduto(x.getIdProduto()).orElse(new Estoque());e.setProduto(produtos.findById(x.getIdProduto()).orElseThrow(()->new ApiException("Produto nao encontrado",HttpStatus.NOT_FOUND)));e.setQuantidade(x.getQuantidade());e.setEstoqueMinimo(x.getEstoqueMinimo());if(x.getIdLoja()!=null)e.setLoja(lojas.findById(x.getIdLoja()).orElseThrow(()->new ApiException("Loja nao encontrada",HttpStatus.NOT_FOUND)));return new EstoqueResponse(r.save(e));} public void excluir(Integer id){if(!r.existsById(id))throw new ApiException("Estoque nao encontrado",HttpStatus.NOT_FOUND);r.deleteById(id);} }